-- ************************************** Project
CREATE TABLE Project
(
 project_number  numeric(5) NOT NULL,
 start_date_act  date,
 end_date_act    date,
 customer_number numeric(5),
 employee_number numeric(5),
 project_name    char(30),
 project_label   char(80),

 CONSTRAINT PK_Project PRIMARY KEY ( project_number ),
 CONSTRAINT FK_Project_Customer FOREIGN KEY ( customer_number ) REFERENCES Customer ( customer_number ),
 CONSTRAINT FK_Project_Employee FOREIGN KEY ( employee_number ) REFERENCES Employee ( employee_number )
);
